int binarySearch(int A[], int n, int key) {
    int low=0, high=n-1;
    while (low<=high) {
        int mid=low+(high-low)/2;
        if (A[mid]==key) return mid;
        if (A[mid]<key) low=mid+1;
        else high=mid-1;
    }
    return -1;
}
\end{codeblock}

