erase(t,key):
    if t为空: return 空
    if key<t.key: t.left=erase(t.left,key)
    else if key>t.key: t.right=erase(t.right,key)
    else:
        if t.left为空: 保存t.right，释放t，返回保存值
        if t.right为空: 保存t.left，释放t，返回保存值
        q=t.right；沿q.left找到右子树最小结点
        t.key=q.key（记录有附加字段时一并复制）
        t.right=erase(t.right,q.key)
    return t
\end{codeblock}

